// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    BANK_SAFE c;
    LogFile lf;

    function setUp() public { 
        c = new BANK_SAFE();
        lf = new LogFile();
        // set the log file before initializing so calls to Deposit/Collect won't revert due to missing log
        c.SetLogFile(address(lf));
    }

    // fuzzed params: depositor address and amounts
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 withdrawAmt) public {
        vm.assume(depositAmt <= VALUE_CAP);
        // keep depositor as a non-zero address to be meaningful
        vm.assume(depositor != address(0));
        // bound depositAmt and withdrawAmt to reasonable ranges to avoid trivial overflows in the test harness
        depositAmt = bound(depositAmt, 0, 1 ether);
        withdrawAmt = bound(withdrawAmt, 0, 1 ether);

        // fund depositor so it can deposit and also to receive withdrawals
        vm.deal(depositor, 2 ether);

        // depositor makes a deposit (via Deposit payable)
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // record pre-balance stored in contract for this depositor
        uint256 preStored = c.balances(depositor);

        // Attempt to Collect(withdrawAmt). Collect only takes effect if balances[msg.sender] >= MinSum && balances[msg.sender] >= _am
        // For generality, ensure MinSum is zero so condition depends only on balances >= _am
        // We must call SetMinSum before initialization; ensure we didn't Initialize() in setup. SetMinSum guarded by intitalized flag.
        // Set MinSum to zero to avoid blocking Collect due to MinSum
        c.SetMinSum(0);

        bool ok;
        // call Collect as depositor; capture whether it succeeded or reverted
        vm.prank(depositor);
        try c.Collect(withdrawAmt) { ok = true; } catch { ok = false; }

        uint256 postStored = c.balances(depositor);

        // GENERAL RULE: If Collect succeeded (ok == true), then the stored balance must be >= preStored - withdrawAmt
        // i.e., the contract must not deduct more than the requested _am from stored balances
        if (ok) {
            // safe subtraction: if withdrawAmt > preStored under correct contract Collect should not have succeeded
            // but since ok==true we can assert postStored >= preStored - withdrawAmt
            // express as: postStored + withdrawAmt >= preStored to avoid underflow in solidity arithmetic
            assertTrue(postStored + withdrawAmt >= preStored);
        } else {
            // if Collect reverted / did not proceed then no relation guaranteed; still assert that stored balance didn't increase unexpectedly
            // require postStored == preStored in that case (Collect didn't go through so state shouldn't change)
            assertTrue(postStored == preStored);
        }
    }
}

// Minimal LogFile helper as in reference so c can call it; it simply records messages.
contract LogFile {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val,string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
